import { IconPhoto } from "@airbus/icons";
import { svgColor, svgDashedBorder, svgUri } from "../../helpers";
import { StyleFn } from "..";

export const FileUpload: StyleFn = (theme, mode) => {
  const {
    color,
    font,
    size: { spacing, radius },
  } = theme;

  const rootStyles = {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    width: 312,
    padding: spacing[16],
    gap: spacing[8],
    color: color.text.neutral.default[mode],
    fontSize: font.size.small,
    borderRadius: radius[3],
    backgroundColor: color.surface.componentbackground.minimal[mode],
  };

  return {
    root: {
      ...rootStyles,
      position: "relative",
      backgroundImage: svgDashedBorder(color.border.neutral.strong[mode], 3),
    },
    browse: {
      "& span": {
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      },
    },
    accept: {
      fontSize: font.size.small,
      fontWeight: font.weight.regular,
      lineHeight: font.lineheight.small,
      paddingBottom: spacing[8],
    },
    files: {
      width: 312,
      marginTop: spacing[16],
      display: "flex",
      flexDirection: "column",
      gap: spacing[8],
    },
    message: {
      pointerEvents: "none",
    },
    placeholder: {
      pointerEvents: "none",
      width: spacing[40],
      height: spacing[40],
      backgroundImage: svgUri(
        svgColor(IconPhoto.data, color.text.accent.corporate[mode])
      ),
      backgroundRepeat: "no-repeat",
      backgroundSize: "100%",
    },
    supportedFiles: {
      display: "flex",
      flexDirection: "column",
      justifyContent: "center",
      alignItems: "center",
    },
    overlay: {
      ...rootStyles,
      backgroundColor: color.surface.elevation[6][mode],
      // let drag event pass through to parent
      pointerEvents: "none",
      position: "absolute",
      top: 0,
      bottom: 0,
      left: 0,
      right: 0,
      zIndex: 1,
      backgroundImage: svgDashedBorder(color.border.accent.focus[mode], 3, 4),
    },
  };
};

export const FileItem: StyleFn = (theme, mode) => {
  const {
    color,
    font,
    size: { spacing, radius },
  } = theme;

  return {
    root: {
      display: "flex",
      flexDirection: "column",
      position: "relative",
      borderRadius: radius[3],
      padding: `${spacing[12]} ${spacing[8]}`,
      color: color.text.neutral.default[mode],
      gap: spacing[4],
      backgroundColor: color.surface.componentbackground.minimal[mode],
      fontSize: font.size.medium,
    },
    name: {
      lineHeight: font.lineheight.small,
      padding: `${spacing[2]} ${spacing[32]} ${spacing[2]} 0`,
      wordWrap: "break-word",
    },
    removeButton: {
      color: `${color.text.accent.corporate[mode]} !important`,
      position: `${"absolute"} !important`,
      top: `${spacing[8]} !important`,
      right: `${spacing[8]} !important`,
    },
    retry: {
      paddingBottom: spacing[8],
    },
    retryButton: {
      alignSelf: "baseline",
    },
    status: {
      display: "flex",
      gap: spacing[8],
      alignItems: "center",
      fontSize: font.size.small,
      "& svg, & i": {
        margin: 0,
        width: spacing[24],
        height: spacing[24],
        fontSize: spacing[24],
        fill: "currentColor",
        display: "inline-flex",
      },
    },
    _error: {
      "& $status": {
        color: color.surface.feedback.error.default[mode],
      },
    },
    _success: {
      "& $status": {
        color: color.surface.feedback.success.default[mode],
      },
    },
  };
};
